mapper.select:
SELECT T1.FINPROD_ID, T1.FINPROD_MARKET_ID, T1.FINPROD_TYPE2, T1.FINPROD_NAME, T2.PROD_REGIST_CODE, T1.MANAGER, T1.TRUSTEE_ID, T1.VDATE, T1.MDATE, T1.CALENDAR_ID, T3.CUSTOMER_NAME MANAGER_NAME, T4.CUSTOMER_NAME TRUSTEE_NAME, T5.FEE_NAME FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO T3 ON T3.CUSTOMER_ID = T1.MANAGER LEFT JOIN MST_CUSTOMER_INFO T4 ON T4.CUSTOMER_ID = T1.TRUSTEE_ID LEFT JOIN ( SELECT group_concat(T2.ITEM_VALUE order by (T2.ITEM_VALUE)) FEE_NAME, T1.FINPROD_ID FROM FIN_CASH_INFO T1 LEFT JOIN sys_datadict_list T2 ON T1.CASH_TYPE_2 = T2.ITEM_CODE AND CASH_TYPE_2 IN ( 'C11', 'C12', 'C13' ) AND T2.DICT_CODE = 'CASH_TYPE_2' GROUP BY FINPROD_ID ) T5 ON T5.FINPROD_ID = T1.FINPROD_ID
AND T1.FINPROD_ID IN
#{item}
AND T1.FINPROD_ID IN
#{item}
AND T1.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T1.VDATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
AND T1.VDATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
AND T1.MDATE >= STR_TO_DATE(#{mdateStart},'%Y-%m-%d')
AND T1.MDATE <= STR_TO_DATE(#{mdateEnd},'%Y-%m-%d')
